cudaError_t configure() {
  cudaError_t status = cudaSuccess;
  status = cudaFuncSetAttribute(decode::kernel_sm120_dsv41_mixed_sparse_mla_decode_h8, cudaFuncAttributeMaxDynamicSharedMemorySize, kDecodeSmemBytes);
  if (status != cudaSuccess) return status;
  status = cudaFuncSetAttribute(decode_dual::kernel_sm120_dsv41_mixed_sparse_mla_decode_h8_dual, cudaFuncAttributeMaxDynamicSharedMemorySize, kDecodeSmemBytes);
  if (status != cudaSuccess) return status;
  return status;
}

cudaError_t launch_decode(const DecodeArgs& a, bool dual, dim3 grid, cudaStream_t stream) {
  if (dual) {
    decode_dual::kernel_sm120_dsv41_mixed_sparse_mla_decode_h8_dual<<<grid, kDecodeThreads, kDecodeSmemBytes, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.mid_out, a.mid_lse, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.scratch_split_stride, a.chunks_per_block, a.sm_scale, a.lse_scale, a.write_direct, a.hb_major);
  } else {
    decode::kernel_sm120_dsv41_mixed_sparse_mla_decode_h8<<<grid, kDecodeThreads, kDecodeSmemBytes, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.mid_out, a.mid_lse, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.scratch_split_stride, a.chunks_per_block, a.sm_scale, a.lse_scale, a.write_direct, a.hb_major);
  }
  return cudaGetLastError();
}

// The merge is the programmatic dependent of the decode grid: launched with the Programmatic Dependent Launch
// attribute its CTAs are scheduled while the decode grid drains (the decode signals `griddepcontrol.launch_dependents`
// at its entry, the merge waits on `griddepcontrol.wait` before its first global load); without the attribute the
// wait is a no-op and the merge simply follows the decode in stream order.
cudaError_t launch_merge(const MergeArgs& a, dim3 grid, bool enable_pdl, cudaStream_t stream) {
  cudaLaunchConfig_t config{};
  config.gridDim = grid;
  config.blockDim = dim3(kMergeThreads, 1, 1);
  config.dynamicSmemBytes = kMergeSmemBytes;
  config.stream = stream;
  cudaLaunchAttribute attribute[1];
  attribute[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
  attribute[0].val.programmaticStreamSerializationAllowed = enable_pdl ? 1 : 0;
  config.attrs = attribute;
  config.numAttrs = 1;
  return cudaLaunchKernelEx(&config, merge::kernel_sm120_dsv41_mixed_sparse_mla_merge_h8, a.mid_out, a.mid_lse, a.attn_sink, a.output, a.out_lse, a.num_splits, a.scratch_split_stride, a.lse_scale, a.hb_major);
}

